package com.example.campusmaintenance.controller;
import com.example.campusmaintenance.dto.*; import com.example.campusmaintenance.entity.MaintenanceRequest; import com.example.campusmaintenance.enums.RequestStatus; import com.example.campusmaintenance.service.MaintenanceRequestService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.slf4j.MDC; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/requests") public class MaintenanceRequestController {private final MaintenanceRequestService s; public MaintenanceRequestController(MaintenanceRequestService s){this.s=s;} @GetMapping public ResponseEntity<ApiResponse<List<MaintenanceRequest>>> all(HttpServletRequest q){return ResponseEntity.ok(ok("Maintenance requests retrieved successfully",s.all(),q));} @GetMapping("/{id}") public ResponseEntity<ApiResponse<MaintenanceRequest>> one(@PathVariable Long id,HttpServletRequest q){return ResponseEntity.ok(ok("Maintenance request retrieved successfully",s.one(id),q));} @PostMapping public ResponseEntity<ApiResponse<MaintenanceRequest>> create(@Valid @RequestBody MaintenanceRequestDto d,HttpServletRequest q){return ResponseEntity.status(201).body(ok("Maintenance request created successfully",s.create(d),q));} @PutMapping("/{id}") public ResponseEntity<ApiResponse<MaintenanceRequest>> update(@PathVariable Long id,@Valid @RequestBody MaintenanceRequestDto d,HttpServletRequest q){return ResponseEntity.ok(ok("Maintenance request updated successfully",s.update(id,d),q));} @PatchMapping("/{id}/status") public ResponseEntity<ApiResponse<MaintenanceRequest>> status(@PathVariable Long id,@RequestParam RequestStatus status,HttpServletRequest q){return ResponseEntity.ok(ok("Maintenance request status updated successfully",s.status(id,status),q));} @DeleteMapping("/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id,HttpServletRequest q){s.delete(id);return ResponseEntity.ok(ok("Maintenance request deleted successfully",null,q));} private <T> ApiResponse<T> ok(String m,T d,HttpServletRequest q){return new ApiResponse<>(true,m,d,q.getRequestURI(),MDC.get("correlationId"));}}
